/* =========================================================
   Plex -> Netflix-ish theme (Stylus)
   Works best on Plex Web.
   Customize the variables under :root
   ========================================================= */

/* ---------- Customize here ---------- */
:root {
  --nf-bg: #0b0b0f;               /* page background */
  --nf-surface: rgba(255,255,255,.04);
  --nf-surface-2: rgba(255,255,255,.07);
  --nf-text: rgba(255,255,255,.92);
  --nf-text-dim: rgba(255,255,255,.68);
  --nf-red: #e50914;              /* netflix-ish accent */
  --nf-radius: 14px;
  --nf-shadow: 0 18px 60px rgba(0,0,0,.55);
  --nf-shadow-soft: 0 10px 30px rgba(0,0,0,.35);
  --nf-poster-scale: 1.06;        /* hover zoom */
  --nf-row-gap: 10px;
  --nf-font: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
}

/* ---------- Global background + text ---------- */
html, body {
  background: var(--nf-bg) !important;
  color: var(--nf-text) !important;
  font-family: var(--nf-font) !important;
}

/* Many Plex containers use inline backgrounds; force them darker */
div, main, section {
  background-color: transparent !important;
}

/* ---------- Reduce “gray wash” overlays ---------- */
*[style*="background"], *[style*="background-color"] {
  /* Don't nuke everything; just soften bright backgrounds */
  filter: saturate(1.05);
}

/* ---------- Top bar tweaks (keep it minimal) ---------- */
header, [class*="TopBar"], [class*="NavBar"], [class*="AppHeader"] {
  background: linear-gradient(to bottom, rgba(11,11,15,.92), rgba(11,11,15,.25)) !important;
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255,255,255,.06) !important;
}

/* Make primary buttons feel “Netflix” */
button, [role="button"] {
  border-radius: calc(var(--nf-radius) - 6px) !important;
}
button:hover, [role="button"]:hover {
  filter: brightness(1.05);
}

/* ---------- Sidebar / left nav (optional minimal look) ---------- */
/* Comment this block out if you want the sidebar unchanged */
aside, [class*="Sidebar"], [class*="SideNav"] {
  background: rgba(11,11,15,.72) !important;
  border-right: 1px solid rgba(255,255,255,.06) !important;
  backdrop-filter: blur(12px);
}

/* Hide some “noise” items if they exist (names differ by version) */
a[href*="podcasts"], a[href*="music"], a[href*="webshows"], a[href*="news"] {
  display: none !important;
}

/* ---------- Row titles / section headers ---------- */
h1, h2, h3, [class*="SectionTitle"], [class*="RowTitle"] {
  color: var(--nf-text) !important;
  letter-spacing: .2px;
}
h2, h3, [class*="RowTitle"] {
  font-weight: 650 !important;
}

/* Add a subtle red “accent” to headings (very Netflix) */
h2::before, h3::before,
[class*="RowTitle"]::before {
  content: "";
  display: inline-block;
  width: 10px;
  height: 10px;
  margin-right: 10px;
  border-radius: 3px;
  background: var(--nf-red);
  opacity: .85;
  transform: translateY(-1px);
}

/* ---------- Card / poster styling ---------- */
/* Plex uses many different card wrappers; target broadly */
[class*="Card"], [class*="Item"], [class*="Poster"], [class*="MetadataPoster"],
a[class*="Card"], a[class*="Item"] {
  border-radius: var(--nf-radius) !important;
  overflow: hidden !important;
}

/* Poster image itself */
img {
  border-radius: var(--nf-radius) !important;
}

/* Make poster grids feel tighter and more Netflix-like */
[class*="Row"], [class*="Hub"], [class*="Carousel"] {
  gap: var(--nf-row-gap) !important;
}

/* Hover zoom effect */
[class*="Card"]:hover,
[class*="Item"]:hover,
[class*="Poster"]:hover,
a[class*="Card"]:hover,
a[class*="Item"]:hover {
  transform: scale(var(--nf-poster-scale)) !important;
  z-index: 5 !important;
  box-shadow: var(--nf-shadow) !important;
  transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease !important;
}

/* Make non-hover state still clean */
[class*="Card"], [class*="Item"], [class*="Poster"], a[class*="Card"], a[class*="Item"] {
  box-shadow: var(--nf-shadow-soft) !important;
  transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease !important;
}

/* Dim text under posters slightly */
[class*="Metadata"], [class*="subtitle"], [class*="SubTitle"], [class*="Secondary"] {
  color: var(--nf-text-dim) !important;
}

/* ---------- “Continue Watching” / progress bars ---------- */
progress, [class*="Progress"], [class*="progress"] {
  accent-color: var(--nf-red) !important;
}
[class*="ProgressBar"], [class*="progressBar"] {
  background: rgba(255,255,255,.12) !important;
}
[class*="ProgressBar"] * {
  background: var(--nf-red) !important;
}

/* ---------- Dialogs / modals ---------- */
[role="dialog"], [class*="Modal"], [class*="Dialog"] {
  background: rgba(20,20,28,.92) !important;
  border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: calc(var(--nf-radius) + 2px) !important;
  box-shadow: var(--nf-shadow) !important;
  backdrop-filter: blur(14px);
}

/* ---------- Scrollbar (optional) ---------- */
*::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
*::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.14);
  border-radius: 999px;
}
*::-webkit-scrollbar-thumb:hover {
  background: rgba(255,255,255,.22);
}

